{
  "title": "A Softer Ubud Sunday",
  "summary": "We ease off the temple trail and spend the day wandering Ubud's green edges, market lanes and a long, lazy dinner.",
  "stops": [
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The one keeper on the list, and worth it: those green steps wake you up better than coffee.",
      "kind": "activity"
    },
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": null,
      "note": "No temples, Leo, I heard you. Just a busy little market full of colour, chatter and things you didn't know you needed.",
      "kind": "activity"
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "A calm vegan lunch stop, because everyone at the table should leave happy and full.",
      "kind": "meal"
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle ridge walk with no roofs, no carvings, just sky and green. The sun won’t wait, but this path doesn’t rush either.",
      "kind": "activity"
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "A long, slow dinner to end the day properly. Terima kasih (thank you) to whoever suggested we linger.",
      "kind": "meal"
    }
  ]
}
